import { ACTIONS_PER_MONTH, CITY_SPECS, FACTIONS, OFFICES, SKILLS, SCENARIOS, TECHNOLOGIES, NATIONAL_POLICIES, activeTreaty, advanceMonth, appointGovernor, appointOffice, armyAction, availableOfficers, campaignSummary, capturedOfficers, cityAction, createCampaign, diplomacyAction, disbandArmy, factionArmies, factionCities, factionOfficers, factionPower, formatYear, getGovernor, marchArmy, migrateCampaign, migratePopulation, neighbors, officerById, prisonerAction, raiseArmy, recruitOfficer, relationship, rewardOfficer, setDelegated, setNationalPolicy, startResearch, wanderingOfficers } from "./shared-rules.js";

const SAVE_PREFIX="youyi-three-kingdoms-campaign-v1-slot-";
const $=selector=>document.querySelector(selector);
const el={
  era:$("#eraText"),turn:$("#turnText"),money:$("#moneyText"),food:$("#foodText"),troops:$("#troopText"),cities:$("#cityText"),prestige:$("#prestigeText"),moneyFlow:$("#moneyFlow"),foodFlow:$("#foodFlow"),
  realm:$("#realmPanel"),detail:$("#detailPanel"),routes:$("#routeLayer"),borders:$("#borderLayer"),armies:$("#armyLayer"),cityLayer:$("#cityLayer"),legend:$("#legend"),action:$("#actionText"),hint:$("#modeHint"),toast:$("#mapToast"),
  dispatch:$("#dispatchPanel"),dispatchList:$("#dispatchList"),reportCount:$("#reportCount"),start:$("#startModal"),factionGrid:$("#factionGrid"),continue:$("#continueButton"),
  confirm:$("#confirmModal"),confirmEye:$("#confirmEyebrow"),confirmTitle:$("#confirmTitle"),confirmBody:$("#confirmBody"),accept:$("#acceptConfirm"),cancel:$("#cancelConfirm"),flash:$("#battleFlash"),battleResult:$("#battleResult"),battleSummary:$("#battleSummary"),live:$("#liveRegion"),scenario:$("#scenarioSelect"),scenarioDescription:$("#scenarioDescription"),speed:$("#speedButton")
};
let state=null,mode="domestic",sound=true,confirmAction=null,toastTimer=null,activeSlot=1,speed=1;

function n(value){return Math.max(0,Math.round(value)).toLocaleString("zh-CN")}
function signed(value){const rounded=Math.round(value);return `${rounded>=0?"+":"-"}${Math.abs(rounded).toLocaleString("zh-CN")}`}
function faction(id){return FACTIONS.find(f=>f.id===id)}
function own(city){return city?.owner===state?.playerFaction}
function notify(message){el.toast.textContent=message;el.live.textContent=message;el.toast.classList.add("show");clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.toast.classList.remove("show"),1800)}
function tone(freq=430,duration=.07){if(!sound)return;try{const ctx=new(window.AudioContext||window.webkitAudioContext)(),osc=ctx.createOscillator(),gain=ctx.createGain();osc.frequency.value=freq;osc.type="triangle";gain.gain.setValueAtTime(.035,ctx.currentTime);gain.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+duration);osc.connect(gain).connect(ctx.destination);osc.start();osc.stop(ctx.currentTime+duration)}catch{}}
function saveKey(slot=activeSlot){return `${SAVE_PREFIX}${slot}`}
function persist(slot=activeSlot){if(state)localStorage.setItem(saveKey(slot),JSON.stringify(state))}
function loadSaved(slot=activeSlot){try{return migrateCampaign(JSON.parse(localStorage.getItem(saveKey(slot))))}catch{return null}}

function initStart(){
  el.factionGrid.innerHTML=FACTIONS.map(f=>`<button class="faction-option" style="--faction:${f.color}" data-faction="${f.id}"><i>${f.realm}</i><span><b>${f.name} · ${f.trait}</b><small>${f.bonus}<br>据点：${CITY_SPECS.find(c=>c.id===f.capital)?.name}</small></span></button>`).join("");
  el.factionGrid.addEventListener("click",event=>{const button=event.target.closest("[data-faction]");if(button)startCampaign(button.dataset.faction)});
  el.scenario.onchange=()=>el.scenarioDescription.textContent=SCENARIOS[el.scenario.value].description;
  const saved=loadSaved();if(saved){el.continue.hidden=false;el.continue.onclick=()=>{state=saved;el.start.classList.add("hidden");render();showTutorial(false)}}
}
function startCampaign(id){state=createCampaign(id,el.scenario.value);persist();el.start.classList.add("hidden");tone(520,.15);render();notify(`以${faction(id).name}之名，举兵天下`);showTutorial(true)}
function showTutorial(force=false){if(!force&&localStorage.getItem("youyi-three-kingdoms-tutorial"))return;el.confirmEye.textContent="军师初议";el.confirmTitle.textContent="先安内，再图天下";el.confirmBody.innerHTML="<div class='tutorial-steps'><p><b>一 · 治城</b> 先提高农业与治安，稳定每月钱粮。</p><p><b>二 · 用人</b> 任命高政治武将为太守，高统率武将领军。</p><p><b>三 · 谋国</b> 选择长期国策与科技，再观察边境强弱出兵。</p><p><b>四 · 结盟</b> 盟约有期限，联合进攻能迫使强敌分兵。</p></div>";el.accept.textContent="开始治国";confirmAction=()=>{localStorage.setItem("youyi-three-kingdoms-tutorial","1");closeConfirm();notify("选择己方城池，从第一道政令开始")};el.confirm.classList.remove("hidden")}

function render(){if(!state)return;renderTop();renderRealm();renderMap();renderDetail();renderLogs();renderDock();checkEnding()}
function renderTop(){
  const f=state.factions[state.playerFaction],sum=campaignSummary(state),cities=factionCities(state,state.playerFaction);
  const monthly=cities.reduce((acc,c)=>{acc.money+=Math.floor(c.population*c.commerce/100*.013);acc.food+=Math.floor(c.population*c.agriculture/100*.019)-Math.floor(c.troops*.08);return acc},{money:0,food:0});
  el.era.textContent=formatYear(state);el.turn.textContent=`战役第 ${state.turn} 月`;el.money.textContent=n(f.treasury);el.food.textContent=n(f.food);el.troops.textContent=n(sum.troops);el.cities.textContent=`${sum.cities} 城`;el.prestige.textContent=n(f.prestige);el.moneyFlow.textContent=`月入 ${n(monthly.money)}`;el.foodFlow.textContent=`月余 ${signed(monthly.food)}`;
}
function renderRealm(){
  const f=faction(state.playerFaction),data=state.factions[f.id],sum=campaignSummary(state),allOfficers=factionOfficers(f.id,state),officers=allOfficers.slice().sort((a,b)=>(b.politics+b.command)-(a.politics+a.command)).slice(0,4);
  el.realm.innerHTML=`<div class="realm-banner"><div class="realm-seal" style="background:${f.color}">${f.realm}</div><div><small>君主</small><h2>${f.name}</h2></div></div><div class="realm-trait"><b>${f.trait}</b><span>${f.bonus}</span></div><div class="realm-meta"><div><small>势力</small><b>${n(sum.power)}</b></div><div><small>盟友</small><b>${data.allies.length}</b></div><div><small>城池</small><b>${sum.cities}/36</b></div><div><small>军团</small><b>${sum.armies}</b></div></div><p class="minister-title">帐下重臣 · ${allOfficers.length} 人</p>${officers.map(o=>`<div class="minister"><div class="avatar">${o.name.slice(-1)}</div><div><b>${o.name}</b><small>${o.title} · 忠 ${o.loyalty} · ${o.skill}</small></div></div>`).join("")}`;
}
function renderMap(){
  const seen=new Set(),player=state.playerFaction,selected=state.cities[state.selectedCity];
  el.routes.innerHTML=CITY_SPECS.flatMap(c=>c.neighbors.map(id=>{const key=[c.id,id].sort().join(":");if(seen.has(key))return"";seen.add(key);const b=state.cities[id],hostile=state.cities[c.id].owner!==b.owner;return`<line class="route ${hostile?"hostile":""}" x1="${c.x}" y1="${c.y}" x2="${b.x}" y2="${b.y}"/>`})).join("");
  el.borders.innerHTML=CITY_SPECS.map(c=>{const f=faction(state.cities[c.id].owner);return`<circle cx="${c.x}" cy="${c.y}" r="8" fill="${f.color}" opacity=".085"/>`}).join("");
  el.armies.innerHTML=Object.values(state.armies||{}).map(army=>{const from=state.cities[army.origin]||state.cities[army.location],to=state.cities[army.target]||state.cities[army.location],progress=army.status==="moving"?Math.max(.16,1-army.remaining/Math.max(1,army.totalTravel)) : 1,x=from.x+(to.x-from.x)*progress,y=from.y+(to.y-from.y)*progress,af=faction(army.faction),commander=officerById(state,army.commander),hostile=army.faction!==player;return`${army.status==="moving"?`<line class="march-line ${hostile?"hostile":""}" x1="${from.x}" y1="${from.y}" x2="${to.x}" y2="${to.y}"/>`:""}<g class="army-token ${hostile?"hostile":"friendly"}" data-army="${army.id}" transform="translate(${x} ${y})"><title>${army.name} · ${n(army.troops)}兵 · ${armyStatus(army)}</title><path class="army-pole" d="M0 3V-3.5"/><path class="army-flag" fill="${af.color}" d="M.2-3.3H4l-1 1.5 1 1.5H.2Z"/><circle cx="0" cy="3" r="1.2" fill="${af.light}"/><text x="2" y="-1.4">${commander?.name.slice(-1)||af.realm}</text></g>`}).join("");
  el.cityLayer.innerHTML=CITY_SPECS.map(spec=>{const c=state.cities[spec.id],f=faction(c.owner),isSelected=c.id===state.selectedCity,isTarget=mode==="military"&&own(selected)&&selected.neighbors.includes(c.id)&&!own(c);return`<g class="city-node ${isSelected?"selected":""} ${isTarget?"enemy-target":""}" data-city="${c.id}" tabindex="0" role="button" aria-label="${c.name}，${f.name}所属，驻军${c.troops}"><circle class="halo" cx="${c.x}" cy="${c.y}" r="4.2" stroke="${isTarget?"#a02d27":f.light}"/><circle class="fort" cx="${c.x}" cy="${c.y}" r="2.25" fill="${f.color}"/><path class="roof" d="M${c.x-2.5} ${c.y-.3}L${c.x} ${c.y-2.4}L${c.x+2.5} ${c.y-.3}Z"/><rect class="label-bg" x="${c.x-3.7}" y="${c.y+2.3}" width="7.4" height="3.2" rx=".4"/><text x="${c.x}" y="${c.y+4.65}">${c.name}</text>${c.troops>=18000?`<circle class="army-dot" cx="${c.x+2.6}" cy="${c.y-2.2}" r=".8"/>`:""}</g>`}).join("");
  el.cityLayer.querySelectorAll(".city-node").forEach(node=>{node.addEventListener("click",()=>selectCity(node.dataset.city));node.addEventListener("keydown",e=>{if(e.key==="Enter"||e.key===" "){e.preventDefault();selectCity(node.dataset.city)}})});
  el.armies.querySelectorAll(".army-token").forEach(node=>node.addEventListener("click",()=>{const army=state.armies[node.dataset.army];if(army?.faction===player){mode="military";state.selectedCity=army.location||army.origin;render();notify(`${army.name} · ${armyStatus(army)}`)}}));
  el.legend.innerHTML=FACTIONS.filter(f=>state.factions[f.id].alive).map(f=>`<span><i style="background:${f.color}"></i>${f.name} · ${factionCities(state,f.id).length}</span>`).join("");
}
function armyStatus(army){return({moving:`行军 · ${army.remaining}月`,awaiting:"兵临城下",besieging:`围城 · ${army.siegeTurns}月`,stationed:"驻扎",destroyed:"溃散"})[army.status]||army.status}
function selectCity(id){const previous=state.cities[state.selectedCity],next=state.cities[id];if(mode==="military"&&own(previous)&&previous.neighbors.includes(id)&&!own(next)){openArmyCreate(previous,next);return}state.selectedCity=id;tone(390);renderMap();renderDetail();if(innerWidth<=780)el.detail.classList.add("mobile-open")}

function stat(label,value,max=100,formatted=null){return`<div class="stat-row"><span>${label}</span><div class="bar"><i style="width:${Math.min(100,value/max*100)}%"></i></div><b>${formatted??n(value)}</b></div>`}
function officerCard(officer,actions=""){const role=officer.status==="wandering"?"在野":officer.status==="captured"?"俘虏":officer.title||"校尉";return`<div class="officer-card"><div class="avatar">${officer.name.slice(-1)}</div><div class="officer-copy"><b>${officer.name}<em>${role}</em></b><small>统 ${officer.command} · 政 ${officer.politics} · 智 ${officer.intelligence}</small><span><i>${officer.skill}</i> ${SKILLS[officer.skill]?.description||""}</span><div class="loyalty"><u style="width:${officer.loyalty||45}%"></u></div></div>${actions?`<div class="officer-actions">${actions}</div>`:""}</div>`}
function renderDetail(){
  const c=state.cities[state.selectedCity],f=faction(c.owner),gov=getGovernor(c,state);el.detail.style.setProperty("--faction",f.color);el.detail.style.setProperty("--faction-light",f.light);
  const base=`<div class="city-hero"><span class="city-owner" style="border-color:${f.color}">${f.realm} · ${f.name}</span><small>${c.terrain} · 特产 ${c.specialty}${c.disaster?` · <em>${c.disaster.type} ${c.disaster.months}月</em>`:""}</small><h2>${c.name}</h2></div><div class="detail-tabs"><button class="active">概况</button><button>军务</button><button>城情</button></div><div class="city-stats">${stat("人口",c.population,300000,n(c.population))}${stat("农业",c.agriculture)}${stat("商业",c.commerce)}${stat("治安",c.order)}${stat("城防",c.defense)}${stat("兵力",c.troops,30000,n(c.troops))}${stat("士气",c.morale)}</div><div class="governor-card"><div class="avatar">${gov.name.slice(-1)}</div><div><span>太守 · ${gov.title||"校尉"}</span><b>${gov.name}</b><small>统 ${gov.command} · 政 ${gov.politics} · 智 ${gov.intelligence} · 忠 ${gov.loyalty??"—"}</small></div></div>`;
  el.detail.innerHTML=base+modePanel(c,f);
  el.detail.querySelectorAll("[data-action]").forEach(button=>button.onclick=()=>handlePanelAction(button.dataset.action,button.dataset.target,button.dataset.army));
}
function modePanel(c,f){
  if(mode==="domestic")return`<div class="panel-section"><small>郡县政令 · 每项消耗 1 政令</small><div class="action-grid">${[["farm","劝课农桑","钱 1,200"],["trade","整顿商路","钱 1,400"],["order","巡行乡里","钱 700"],["recruit","征募士卒","钱 800 · 粮 1,600"],["train","操练军伍","钱 600 · 粮 500"],["fortify","增筑城防","钱 1,600"]].map(([a,b,s])=>`<button data-action="${a}" ${!own(c)?"disabled":""}><b>${b}</b><small>${s}</small></button>`).join("")}</div>${!own(c)?"<p class='relations'>敌境不可施政，请选择己方城池。</p>":""}</div>`;
  if(mode==="appoint"){
    const serving=factionOfficers(state.playerFaction,state).slice().sort((a,b)=>b.loyalty-a.loyalty),candidates=availableOfficers(state,state.playerFaction),wanderers=wanderingOfficers(state,c.id),prisoners=capturedOfficers(state,state.playerFaction);
    return`<div class="panel-section"><small>太守与委任</small><button class="wide-action" data-action="delegate" ${!own(c)?"disabled":""}><b>${c.delegated?"收回委任":"委任太守自治"}</b><small>${c.delegated?"下月起停止自动治理":"太守每月自动补强薄弱项目"}</small></button>${own(c)?`<label class="officer-select">更换太守 <select id="governorSelect">${candidates.map(o=>`<option value="${o.id}" ${o.id===c.governor?"selected":""}>${o.name} · 政 ${o.politics} · ${o.skill}</option>`).join("")}</select></label><button class="wide-action" data-action="appoint-governor"><b>颁发太守印</b><small>消耗 1 道政令，忠诚 +3</small></button>`:""}</div><div class="panel-section"><small>${c.name}在野人才 · ${wanderers.length}</small>${wanderers.map(o=>officerCard(o,`<button data-action="recruit-visit" data-target="${o.id}">登门</button><button data-action="recruit-gift" data-target="${o.id}">厚礼</button>`)).join("")||`<p class="relations">此地暂未发现可延揽的人才。</p>`}</div>${prisoners.length?`<div class="panel-section captive-section"><small>帐下俘虏 · ${prisoners.length}</small>${prisoners.map(o=>officerCard(o,`<button data-action="prisoner-persuade" data-target="${o.id}">劝降</button><button data-action="prisoner-release" data-target="${o.id}">释放</button>`)).join("")}</div>`:""}<div class="panel-section roster-section"><small>麾下武将 · ${serving.length}</small>${serving.slice(0,10).map(o=>officerCard(o,o.ruler?"":`<button data-action="reward-officer" data-target="${o.id}">赏赐</button><button data-action="appoint-office" data-target="${o.id}">授官</button>`)).join("")}</div>`;
  }
  if(mode==="military"){
    const allArmies=factionArmies(state,state.playerFaction).slice().sort((a,b)=>(a.location===c.id?-1:1)-(b.location===c.id?-1:1)),targets=own(c)?neighbors(state,c.id).filter(x=>!own(x)):[];
    const armyCards=allArmies.map(a=>{const commander=officerById(state,a.commander),place=state.cities[a.target||a.location||a.origin],canAct=["awaiting","besieging","stationed"].includes(a.status);return`<div class="corps-card ${a.supply==="断绝"?"cut-off":""}"><div class="corps-head"><span><b>${a.name}</b><small>${place?.name||"行军中"} · ${armyStatus(a)}</small></span><em>${n(a.troops)}</em></div><div class="corps-bars"><span>粮 ${n(a.food)}</span><span>士气 ${a.morale}</span><span>粮道 ${a.supply}</span></div>${canAct?`<div class="corps-actions">${a.status==="awaiting"||a.status==="besieging"?`<button data-action="army-assault" data-army="${a.id}">强攻</button>${a.status==="awaiting"?`<button data-action="army-besiege" data-army="${a.id}">围困</button>`:""}<button data-action="army-retreat" data-army="${a.id}">撤退</button>`:`<button data-action="army-march" data-army="${a.id}">继续进军</button><button data-action="army-disband" data-army="${a.id}">归营</button>`}</div>`:""}<small class="corps-officer">${commander?.title||"校尉"} ${commander?.name||"未知"} · ${commander?.skill||""}</small></div>`}).join("");
    return`<div class="panel-section corps-section"><small>在外军团 · ${allArmies.length}</small>${armyCards||`<p class="relations">尚无在外军团。选择敌城组建第一支军团。</p>`}</div><div class="panel-section"><small>${own(c)?"接壤敌城 · 编制新军团":"军事情报"}</small><div class="target-list">${targets.length?targets.map(t=>{const tf=faction(t.owner);return`<button class="target-card" data-action="raise-army" data-target="${t.id}"><span><b>${t.name}</b>　${tf.name}</span><em>${n(t.troops)} 兵</em></button>`}).join(""):`<p class="relations">${own(c)?"此城暂无敌境接壤。":"选择一座己方城池作为出征地。"}</p>`}</div></div>`;
  }
  if(mode==="diplomacy"){
    if(own(c))return`<div class="panel-section"><small>外交目标</small><p class="relations">请选择其他势力的城池，派遣使者。</p></div>`;const rel=relationship(state,state.playerFaction,c.owner),allied=state.factions[state.playerFaction].allies.includes(c.owner),treaty=activeTreaty(state,state.playerFaction,c.owner);return`<div class="panel-section"><small>${f.name} · ${treaty?`${treaty.type==="alliance"?"同盟":"停战"}余 ${treaty.expires-state.turn} 月`:"无盟约"}</small><div class="relations"><span>敌视</span><i><span style="width:${(rel+100)/2}%"></span></i><span>亲善 ${rel}</span></div>${[["gift","馈赠财货","钱 3,000 · 关系 +18"],["truce","议定停战","12 个月不可互攻"],["alliance",allied?"同盟已缔结":"提议同盟","盟期 24 个月"],["joint","共同进攻","邀请盟友夹击强敌"],["sow","离间","降低敌将忠诚"],["turncoat","策反","争取低忠诚敌将"],["counterspy","反间","十二个月抵御敌谋"],["threaten","威压诸侯","以国力迫其屈服"]].map(([a,b,s])=>`<button class="wide-action ${a==="threaten"?"danger":""}" data-action="${a}" ${a==="joint"&&!allied?"disabled":""}><b>${b}</b><small>${s}</small></button>`).join("")}</div>`;
  }
  const sum=campaignSummary(state),rank=FACTIONS.filter(x=>state.factions[x.id].alive).sort((a,b)=>factionPower(state,b.id)-factionPower(state,a.id)),mine=state.factions[state.playerFaction];return`<div class="panel-section"><small>国家经营 · 当前国策 ${NATIONAL_POLICIES[mine.policy].name}</small>${Object.entries(NATIONAL_POLICIES).map(([id,p])=>`<button class="wide-action" data-action="policy-${id}" ${mine.policy===id?"disabled":""}><b>${p.name}</b><small>${p.description}</small></button>`).join("")}</div><div class="panel-section"><small>科技树 ${mine.research?`· ${TECHNOLOGIES[mine.research.id].name}余 ${mine.research.remaining} 月`:""}</small>${Object.entries(TECHNOLOGIES).map(([id,t])=>`<button class="wide-action" data-action="research-${id}" ${mine.research||mine.technologies.includes(id)?"disabled":""}><b>${mine.technologies.includes(id)?"✓ ":""}${t.name}</b><small>${t.description} · 钱 ${n(t.cost)}</small></button>`).join("")}</div><div class="panel-section"><small>天下大势 · 我方排名</small><div class="target-list">${rank.map((x,i)=>`<div class="target-card"><span><b>${i+1}. ${x.name}</b>　${factionCities(state,x.id).length} 城</span><em>${n(factionPower(state,x.id))}</em></div>`).join("")}</div><p class="relations">统一进度 <i><span style="width:${sum.cities/36*100}%"></span></i> ${sum.cities}/36</p>${own(c)?`<button class="wide-action" data-action="migrate"><b>迁徙人口至邻城</b><small>迁民 10,000 · 钱 800</small></button>`:""}</div>`;
}

function handlePanelAction(action,target,armyId){
  const c=state.cities[state.selectedCity];
  try{
    if(["farm","trade","order","recruit","train","fortify"].includes(action)){state=cityAction(state,c.id,action);tone(520);persist();render();notify("政令已施行")}
    else if(action==="delegate"){state=setDelegated(state,c.id,!c.delegated);tone(470);persist();render();notify(c.delegated?"已收回委任":"太守将自主治理")}
    else if(action==="appoint-governor"){state=appointGovernor(state,c.id,$("#governorSelect").value);persist();tone(520);render();notify("太守任命已生效")}
    else if(action==="recruit-visit"){state=recruitOfficer(state,c.id,target,"visit");persist();tone(500);render();notify(state.logs[0].body)}
    else if(action==="recruit-gift"){state=recruitOfficer(state,c.id,target,"gift");persist();tone(560);render();notify(state.logs[0].body)}
    else if(action==="reward-officer"){state=rewardOfficer(state,target);persist();render();notify(state.logs[0].body)}
    else if(action==="appoint-office")openOfficeModal(target);
    else if(action==="prisoner-persuade"){state=prisonerAction(state,target,"persuade");persist();render();notify(state.logs[0].body)}
    else if(action==="prisoner-release"){state=prisonerAction(state,target,"release");persist();render();notify(state.logs[0].body)}
    else if(action==="raise-army")openArmyCreate(c,state.cities[target]);
    else if(action==="army-assault")executeArmyAction(armyId,"assault");
    else if(action==="army-besiege")executeArmyAction(armyId,"besiege");
    else if(action==="army-retreat")executeArmyAction(armyId,"retreat");
    else if(action==="army-disband"){state=disbandArmy(state,armyId);persist();render();notify("军团已归营")}
    else if(action==="army-march")openArmyMarch(armyId);
    else if(["gift","truce","alliance","joint","sow","turncoat","counterspy","threaten"].includes(action))openDiplomacy(c.owner,action);
    else if(action.startsWith("policy-")){state=setNationalPolicy(state,action.slice(7));persist();render();notify(state.logs[0].body)}
    else if(action.startsWith("research-")){state=startResearch(state,action.slice(9));persist();render();notify(state.logs[0].body)}
    else if(action==="migrate")openMigration(c);
  }catch(error){tone(170,.12);notify(error.message)}
}
function openOfficeModal(officerId){const officer=officerById(state,officerId);el.confirmEye.textContent="策命授官";el.confirmTitle.textContent=`擢用${officer.name}`;el.accept.textContent="颁下印绶";el.confirmBody.innerHTML=`${officerCard(officer)}<label class="select-order">授予官职 <select id="officeSelect">${Object.entries(OFFICES).map(([name,data])=>`<option value="${name}" ${name===officer.title?"selected":""}>${name} · 钱 ${n(data.cost)}</option>`).join("")}</select></label><p>将军类官职增强统兵，军师增强围城，尚书增强担任太守时的治理收益。授官同时提升 6 点忠诚。</p>`;confirmAction=()=>{try{state=appointOffice(state,officerId,$("#officeSelect").value);persist();closeConfirm();tone(560);render();notify(state.logs[0].body)}catch(error){closeConfirm();notify(error.message)}};el.confirm.classList.remove("hidden")}
function openArmyCreate(from,to){
  if(!own(from))return notify("请先选择己方出征城池");const officers=availableOfficers(state,state.playerFaction).sort((a,b)=>b.command-a.command),maxTroops=from.troops-1200;if(maxTroops<3000)return notify(`${from.name}兵力不足，无法组建军团`);if(!officers.length)return notify("当前没有可任命的武将");
  const defaultTroops=Math.max(3000,Math.min(maxTroops,Math.floor(from.troops*.46))),maxFood=Math.max(1,Math.min(state.factions[state.playerFaction].food,Math.max(6000,defaultTroops))),defaultFood=Math.min(maxFood,Math.ceil(defaultTroops*.36));
  el.confirmEye.textContent="军团编制";el.confirmTitle.textContent=`${from.name} → ${to.name}`;el.accept.textContent="授旗出征";el.confirmBody.innerHTML=`<div class="battle-preview"><div><span>${from.name}可用</span><b>${n(from.troops)}</b></div><i>行</i><div><span>${to.name}守军</span><b>${n(to.troops)}</b></div></div><div class="army-form"><label>出征兵力 <input id="troopSlider" type="range" min="3000" max="${maxTroops}" value="${defaultTroops}" step="500"><b id="troopValue">${n(defaultTroops)}</b></label><label>携带粮草 <input id="foodSlider" type="range" min="${Math.ceil(defaultTroops*.2)}" max="${maxFood}" value="${defaultFood}" step="500"><b id="foodValue">${n(defaultFood)}</b></label><label>军团主将 <select id="commanderSelect">${officers.map(o=>`<option value="${o.id}">${o.name} · 统 ${o.command}</option>`).join("")}</select></label><label>军团副将 <select id="deputySelect"><option value="">不设副将</option>${officers.slice(1).map(o=>`<option value="${o.id}">${o.name} · 智 ${o.intelligence}</option>`).join("")}</select></label></div><p>军团将携粮独立行动。抵达后可强攻、围困或撤退；粮道被切断会导致士气下降和逃兵。</p>`;
  const troopInput=$("#troopSlider"),foodInput=$("#foodSlider");troopInput.oninput=()=>{$("#troopValue").textContent=n(troopInput.value);foodInput.min=Math.ceil(Number(troopInput.value)*.2);if(Number(foodInput.value)<Number(foodInput.min)){foodInput.value=foodInput.min;$("#foodValue").textContent=n(foodInput.value)}};foodInput.oninput=()=>$("#foodValue").textContent=n(foodInput.value);
  confirmAction=()=>{try{state=raiseArmy(state,from.id,to.id,{troops:Number(troopInput.value),food:Number(foodInput.value),commanderId:$("#commanderSelect").value,deputyId:$("#deputySelect").value||null});persist();closeConfirm();tone(560,.15);mode="military";render();notify(`军团已出征，向${to.name}行军`)}catch(error){closeConfirm();notify(error.message)}};el.confirm.classList.remove("hidden")
}
function executeArmyAction(armyId,action){
  const army=state.armies[armyId];if(!army)return notify("军团已不存在");if(action==="assault"){const city=state.cities[army.target];el.confirmEye.textContent="围城军令";el.confirmTitle.textContent=`强攻${city.name}？`;el.accept.textContent="击鼓攻城";el.confirmBody.innerHTML=`<div class="battle-preview"><div><span>${army.name}</span><b>${n(army.troops)}</b></div><i>攻</i><div><span>${city.name}守军</span><b>${n(city.troops)}</b></div></div><p>强攻会立即决出胜负，城防越高，攻方伤亡越大。也可以取消后选择长期围困。</p>`;confirmAction=()=>{try{state=armyAction(state,armyId,"assault");const report=state.lastBattle;persist();closeConfirm();showBattle(report);render()}catch(error){closeConfirm();notify(error.message)}};el.confirm.classList.remove("hidden");return}
  try{state=armyAction(state,armyId,action);persist();tone(440);render();notify(action==="besiege"?"已合围敌城，下月开始削弱城防":"军团正在撤回出发城池")}catch(error){notify(error.message)}
}
function openArmyMarch(armyId){
  const army=state.armies[armyId],targets=neighbors(state,army.location).filter(c=>c.owner!==army.faction&&!state.factions[army.faction].allies.includes(c.owner));if(!targets.length)return notify("此地没有可进军的敌城");el.confirmEye.textContent="军团转进";el.confirmTitle.textContent=`调动${army.name}`;el.accept.textContent="下达军令";el.confirmBody.innerHTML=`<p>军团将从${state.cities[army.location].name}继续前进，现有兵力与粮草不会返回城中。</p><label class="select-order">选择目标 <select id="marchTarget">${targets.map(c=>`<option value="${c.id}">${c.name} · ${n(c.troops)}守军</option>`).join("")}</select></label>`;confirmAction=()=>{try{const target=$("#marchTarget").value;state=marchArmy(state,armyId,target);persist();closeConfirm();render();notify(`${army.name}向${state.cities[target].name}进军`)}catch(error){closeConfirm();notify(error.message)}};el.confirm.classList.remove("hidden")
}
function openDiplomacy(target,action){const names={gift:"馈赠财货",truce:"议定停战",alliance:"提议同盟",joint:"共同进攻",sow:"施行离间",turncoat:"暗中策反",counterspy:"布置反间",threaten:"威压诸侯"},f=faction(target);el.confirmEye.textContent="外交 · 纵横";el.confirmTitle.textContent=`对${f.name}${names[action]}`;el.confirmBody.innerHTML=`<p>此行动消耗一道政令。外交条约均有明确期限，计谋成功率取决于军师智力、科技与双方形势。</p>`;confirmAction=()=>{try{state=diplomacyAction(state,target,action);persist();closeConfirm();tone(560);render();notify(state.logs[0].body)}catch(error){closeConfirm();notify(error.message)}};el.confirm.classList.remove("hidden")}
function openMigration(from){const targets=neighbors(state,from.id).filter(own);if(!targets.length)return notify("没有相邻的己方城市可接收人口");el.confirmEye.textContent="国家经营";el.confirmTitle.textContent=`迁出${from.name}民户`;el.confirmBody.innerHTML=`<p>迁民可快速充实边境或新占城市，但会略微降低迁出地治安。</p><label class="select-order">迁往 <select id="migrationTarget">${targets.map(c=>`<option value="${c.id}">${c.name} · 人口 ${n(c.population)}</option>`).join("")}</select></label>`;confirmAction=()=>{try{state=migratePopulation(state,from.id,$("#migrationTarget").value,10000);persist();closeConfirm();render();notify(state.logs[0].body)}catch(error){closeConfirm();notify(error.message)}};el.confirm.classList.remove("hidden")}
function closeConfirm(){el.confirm.classList.add("hidden");el.accept.textContent="确认";confirmAction=null}
function showBattle(report){el.battleResult.textContent=report.victory?"破城克敌":"鸣金收兵";el.battleSummary.textContent=`折损 ${n(report.atkLoss)} · 敌军折损 ${n(report.defLoss)}`;el.flash.classList.remove("show");void el.flash.offsetWidth;el.flash.classList.add("show");tone(report.victory?620:180,.28)}
function renderLogs(){const replay=state.history.slice(-8).reverse().map(h=>`<article class="replay"><small>${h.year}年${h.month}月 · ${h.cities}城</small><h3>${h.headline||"月度结算"}</h3><p>势力 ${n(h.power)} · 钱 ${n(h.treasury)} · 粮 ${n(h.food)}</p></article>`).join("");el.dispatchList.innerHTML=state.logs.slice(0,12).map((log,index)=>`<article><small>${index===0?"本月新报":formatYear(state)}</small><h3>${log.title}</h3><p>${log.body}</p></article>`).join("")+`<div class="replay-title">战役回放</div>${replay}`;el.reportCount.textContent=`${Math.min(9,state.logs.length)} 封军报`}
function renderDock(){el.action.textContent=Array.from({length:ACTIONS_PER_MONTH},(_,i)=>i<state.actions?"●":"○").join(" ");document.querySelectorAll("[data-mode]").forEach(b=>b.classList.toggle("active",b.dataset.mode===mode));const hints={domestic:"选择己方城池施行政令",appoint:"延揽人才、授予官职与处置俘虏",military:"组建军团，按月行军与围城",diplomacy:"选择他国城池派遣使者",policy:"查看势力排名与统一进度"};el.hint.textContent=hints[mode]}
function checkEnding(){if(state.status!=="finished"||el.confirm.classList.contains("ending-open"))return;el.confirm.classList.add("ending-open");setTimeout(()=>{el.confirmEye.textContent=state.winner==="victory"?"天下归一":"战役终结";el.confirmTitle.textContent=state.winner==="victory"?state.ending?.grade||"四海归心":"基业尽失";el.confirmBody.innerHTML=`<p>${state.logs[0].body}</p><div class="ending-stats"><b>${state.turn}<small>历时月数</small></b><b>${state.stats.maxCities}<small>最大城池</small></b><b>${state.stats.citiesCaptured}<small>攻克城池</small></b><b>${state.stats.battlesWon}<small>胜利战役</small></b></div>`;el.accept.textContent="再开新局";confirmAction=()=>{localStorage.removeItem(saveKey());location.reload()};el.confirm.classList.remove("hidden")},300)}

document.querySelectorAll("[data-mode]").forEach(button=>button.addEventListener("click",()=>{mode=button.dataset.mode;tone(360);renderDock();renderMap();renderDetail()}));
$("#reportsButton").onclick=()=>el.dispatch.classList.toggle("open");$("#dispatchClose").onclick=()=>el.dispatch.classList.remove("open");
$("#saveButton").onclick=()=>{el.confirmEye.textContent="战役存档";el.confirmTitle.textContent="选择存档槽";el.confirmBody.innerHTML=`<div class="save-slots">${[1,2,3].map(slot=>{const saved=loadSaved(slot);return`<button data-slot="${slot}"><b>存档 ${slot}${slot===activeSlot?" · 当前":""}</b><small>${saved?`${saved.scenario} · ${formatYear(saved)} · ${factionCities(saved,saved.playerFaction).length}城`:"空存档"}</small></button>`}).join("")}</div>`;el.confirmBody.querySelectorAll("[data-slot]").forEach(button=>button.onclick=()=>{activeSlot=Number(button.dataset.slot);persist();closeConfirm();tone(600);notify(`战役已保存至存档 ${activeSlot}`)});el.accept.textContent="关闭";confirmAction=closeConfirm;el.confirm.classList.remove("hidden")};$("#soundButton").onclick=event=>{sound=!sound;event.currentTarget.textContent=sound?"♪":"×";if(sound)tone(520)};
el.speed.onclick=()=>{speed=speed===1?3:speed===3?6:1;el.speed.textContent=`×${speed}`;notify(`每次推进 ${speed} 个月`)};
$("#endTurnButton").onclick=()=>{el.confirmEye.textContent="月度结算";el.confirmTitle.textContent=`推进 ${speed} 个月？`;el.confirmBody.innerHTML=`<p>剩余 ${state.actions} 道政令将作废。诸侯将同步执行长期战略，期间可能发生战役、灾害与历史事件。</p>`;confirmAction=()=>{const oldTurn=state.turn;for(let i=0;i<speed&&state.status==="playing";i++)state=advanceMonth(state);persist();closeConfirm();tone(440,.15);render();notify(`战役由第 ${oldTurn} 月推进至第 ${state.turn} 月`)};el.confirm.classList.remove("hidden")};
el.cancel.onclick=closeConfirm;el.accept.onclick=()=>confirmAction?.();el.confirm.addEventListener("click",event=>{if(event.target===el.confirm)closeConfirm()});
document.addEventListener("keydown",event=>{if(event.key==="Escape"){closeConfirm();el.dispatch.classList.remove("open");el.detail.classList.remove("mobile-open")}});

